<?php
declare(strict_types=1);$pageTitle='My Pledges';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/_helpers.php';require_once __DIR__.'/_church_engagement.php';require_permission('member.profile.view');ce_install($conn);$mid=current_member_id();
try{if($_SERVER['REQUEST_METHOD']==='POST'){ce_check_csrf();$title=trim((string)($_POST['pledge_title']??''));$amount=max(0,(float)($_POST['pledged_amount']??0));$due=trim((string)($_POST['due_date']??''));$notes=trim((string)($_POST['notes']??''));if($title===''||$amount<=0)throw new RuntimeException('Enter a pledge title and amount.');$due=$due!==''?$due:null;$st=$conn->prepare("INSERT INTO member_pledges(member_id,pledge_title,pledged_amount,due_date,notes) VALUES(?,?,?,?,?)");$st->bind_param('isdss',$mid,$title,$amount,$due,$notes);$st->execute();$st->close();ce_redirect('pledges.php','Your pledge has been saved.');}}catch(Throwable $e){$_SESSION['ce_flash']=['message'=>$e->getMessage(),'type'=>'danger'];}
$rows=mp_rows($conn,"SELECT * FROM member_pledges WHERE member_id=? ORDER BY status='Active' DESC,due_date,id DESC",'i',[$mid]);$total=array_sum(array_map(fn($r)=>(float)$r['pledged_amount'],$rows));$paid=array_sum(array_map(fn($r)=>(float)$r['paid_amount'],$rows));$isSunday=(int)date('w')===0;$after7=date('H:i:s')>='07:00:00';include __DIR__.'/../includes/sidebar.php';?><div class="main-content"><?php include __DIR__.'/../includes/topbar.php';?><div class="content-wrapper"><?php ce_flash();if($isSunday&&$after7&&array_filter($rows,fn($r)=>$r['status']==='Active'&&(float)$r['paid_amount']<(float)$r['pledged_amount'])):?><div class="ce-alarm" id="pledgeAlarm"><strong><i class="fas fa-bell"></i> Sunday Pledge Reminder</strong><br>You have an active church pledge. Please remember your commitment.<button class="btn btn-sm btn-warning" type="button" onclick="enablePledgeReminder()">Enable Reminder Alarm</button></div><?php endif;mp_render_stats([['label'=>'Total Pledged','value'=>$total,'money'=>true,'icon'=>'fa-hand-holding-heart'],['label'=>'Total Paid','value'=>$paid,'money'=>true,'icon'=>'fa-coins'],['label'=>'Balance','value'=>max(0,$total-$paid),'money'=>true,'icon'=>'fa-wallet']]);?><div class="card"><div class="card-header"><h3>Add a Pledge</h3></div><div class="card-body"><form method="post" class="ce-form"><input type="hidden" name="csrf_token" value="<?=mp_h(ce_csrf())?>"><div class="row2"><div><label>Pledge Purpose</label><input class="form-control" name="pledge_title" required></div><div><label>Amount (UGX)</label><input class="form-control" type="number" min="1" step="1" name="pledged_amount" required></div></div><div class="row2"><div><label>Due Date</label><input class="form-control" type="date" name="due_date"></div><div><label>Notes</label><input class="form-control" name="notes"></div></div><button class="btn btn-primary">Save Pledge</button></form></div></div><div class="ce-grid" style="margin-top:18px"><?php foreach($rows as $r):$p=ce_progress((float)$r['paid_amount'],(float)$r['pledged_amount']);?><article class="ce-card"><span class="ce-badge"><?=mp_h($r['status'])?></span><h4><?=mp_h($r['pledge_title'])?></h4><p><strong>Pledged:</strong> UGX <?=mp_money($r['pledged_amount'],0)?><br><strong>Paid:</strong> UGX <?=mp_money($r['paid_amount'],0)?><br><strong>Balance:</strong> UGX <?=mp_money(max(0,(float)$r['pledged_amount']-(float)$r['paid_amount']),0)?><br><strong>Due:</strong> <?=mp_date($r['due_date'])?></p><div class="ce-progress"><span style="width:<?=$p?>%"></span></div></article><?php endforeach;?></div></div></div><script>function enablePledgeReminder(){if('Notification'in window){Notification.requestPermission().then(function(p){if(p==='granted'){new Notification('Sunday Pledge Reminder',{body:'Remember your active church pledge.'});const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=880;g.gain.value=.12;o.start();setTimeout(()=>{o.stop();a.close()},900)}})}};</script><?php mp_standard_styles();ce_styles();require_once __DIR__.'/../includes/footer.php';?>
